198	     *
199	     * @param name to test
200	     * @return true if pet name is already in use
201	     */
202	    public Pet getPet(String name, boolean ignoreNew) {
203	        name = name.toLowerCase();
204	        for (Pet pet : getPetsInternal()) {
205	            if (!ignoreNew || !pet.isNew()) {
206	                String compName = pet.getName();
207	                compName = compName.toLowerCase();
